package com.veyra.storage;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.io.*;import java.nio.file.*;import java.util.*;
@Component public class FilesystemStorageProvider implements FileStorageProvider{private final Path root;private final long max;public FilesystemStorageProvider(@Value("${veyra.storage.root}")String r,@Value("${veyra.storage.max-file-size-mb}")long m)throws IOException{root=Paths.get(r).toAbsolutePath().normalize();max=m*1024*1024;Files.createDirectories(root);}public StoredFile store(InputStream c,String n,String t,long s)throws IOException{if(s<=0||s>max)throw new IllegalArgumentException("INVALID_FILE_SIZE");String e=ext(n);if(e.isBlank())throw new IllegalArgumentException("INVALID_FILE_TYPE");String k=UUID.randomUUID()+e;Files.copy(c,safe(k));return new StoredFile(k,n,t,s);}public InputStream load(String k)throws IOException{return Files.newInputStream(safe(k));}public void delete(String k)throws IOException{Files.deleteIfExists(safe(k));}public boolean exists(String k){return Files.exists(safe(k));}private Path safe(String k){Path p=root.resolve(k).normalize();if(!p.startsWith(root))throw new SecurityException("INVALID_PATH");return p;}private String ext(String n){if(n==null||!n.contains("."))return "";String e=n.substring(n.lastIndexOf('.')).toLowerCase();return Set.of(".pdf",".jpg",".jpeg",".png").contains(e)?e:"";}}